10	import { openRunStream } from '../sse.js';
11	import { targetColor, fmtMs } from '../charts.js';
12	import { levelCountdown, resultsSavedBanner } from './shared.js';
13	
14	const fmtInt = (n) => n.toLocaleString('en-US');
15	
16	const METRICS = {
17	  pushes: { label: 'Throughput' },
18	  latency: { label: 'Latency' },
19	  reliability: { label: 'Reliability' },
20	};
21	
22	export function renderRace(app, arg) {
23	  const [runId, argMetric] = String(arg).split('/');
24	  let metric = METRICS[argMetric] ? argMetric : 'pushes';
25	
26	  const state = {
27	    hello: null,
28	    curLevel: null,
29	    done: null,
30	    isClone: false,
31	    isSession: false,
32	    lanes: {},       // target id → {ok: primary ops, good/errs: ALL ops incl. session clones, rates, lat, els, lane}
33	    finals: {},      // target id → last level_result row (measured window stats), stamped with _level
34	    finalLevel: -1,  // highest level_index seen; a final counts only if it's from this level
35	  };
36	  let es = null;
37	  let ticker = null;
38	  let raf = 0; // coalesces lane DOM updates: replay dispatches thousands of buckets
39	
40	  const opsNoun = () => (state.isClone ? 'clones' : 'pushes');
41	
42	  const badge = h('span', { class: 'badge running' }, 'connecting…');
43	  const clock = h('div', { class: 'race-clock' }, '–:––');
44	  const phase = h('div', { class: 'race-phase' }, '');
45	  const banners = h('div');
46	  const lanesBox = h('div', { class: 'race-lanes' });
47	  const finishBox = h('div');
48	  const science = h('p', { class: 'race-science' });
49	
50	  const seg = h('div', { class: 'seg' }, Object.entries(METRICS).map(([key, m]) =>
51	    h('button', { type: 'button', class: key === metric ? 'on' : '', onclick: () => {
52	      metric = key;
53	      for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.textContent === METRICS[metric].label);
54	      history.replaceState(null, '', `#race/${runId}/${metric}`);
55	      updateLanes();
56	      refinish();
57	    } }, m.label)));
58	
59	  app.append(
60	    h('div', { class: 'race-head' },
61	      h('h1', {}, '⚡ Push race'),
62	      badge,
63	      seg,
64	      h('span', { class: 'spacer' }),
65	      h('a', { class: 'race-alt', href: `#run/${runId}` }, '📊 full dashboard')),
66	    h('div', { class: 'race-timer' }, clock, phase),
67	    banners, lanesBox, finishBox, science);
68	
69	  function buildLanes(targets) {
70	    lanesBox.innerHTML = '';
71	    for (const t of targets) {
72	      const els = {
73	        big: h('div', { class: 'race-total' }, '–'),
74	        unit: h('span', { class: 'race-unit' }, ''),
75	        side: h('div', { class: 'race-rate' }, '–'),
76	        bar: h('div', { class: 'race-bar', style: { '--tcolor': targetColor(t.id), width: '2%' } }),
77	        crown: h('span', { class: 'race-crown' }, ''),
78	        note: h('div', { class: 'race-note' }, t.remote),
79	      };
80	      const lane = h('div', { class: 'race-lane', style: { '--tcolor': targetColor(t.id) } },
81	        h('div', { class: 'race-lane-head' },
82	          h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id) } }),
83	          h('span', { class: 'race-name' }, t.name), els.crown,
84	          h('span', { class: 'spacer' }), els.side),
85	        h('div', { class: 'race-track' }, els.bar, h('span', { class: 'race-flag' }, '🏁')),
86	        h('div', { class: 'race-lane-foot' }, els.big, els.unit, els.note));
87	      state.lanes[t.id] = { ok: 0, good: 0, errs: 0, rates: [], lat: null, pop: false, els, lane };
88	      lanesBox.append(lane);
89	    }
90	  }
91	
92	  // Every metric is maintained simultaneously from the buckets, so switching
93	  // mid-race just re-renders the same lane state through a different lens.
94	  function updateLanes() {
95	    const lanes = Object.values(state.lanes);
96	    if (!lanes.length) return;
97	
98	    if (metric === 'pushes') {
99	      const leader = Math.max(1, ...lanes.map((l) => l.ok));
100	      for (const l of lanes) {
101	        const avg = l.rates.length ? l.rates.reduce((a, b) => a + b, 0) / l.rates.length : 0;
102	        l.els.big.textContent = fmtInt(l.ok);
103	        l.els.unit.textContent = opsNoun();
104	        l.els.side.textContent = `${avg >= 10 ? Math.round(avg) : avg.toFixed(1)} ${opsNoun()}/s`;
105	        l.els.bar.style.width = `${Math.max(2, (l.ok / leader) * 100)}%`;
106	        l.els.crown.textContent = lanes.length > 1 && l.ok === leader && l.ok > 0 ? '👑' : '';
107	      }
108	    } else if (metric === 'latency') {
109	      // Only positive p50s are meaningful; a sub-millisecond p50 can round to 0
110	      // and must not become the divisor (NaN width) or a shared crowned "best".
111	      const p50s = lanes.map((l) => l.lat && l.lat.p50 > 0 ? l.lat.p50 : null).filter((v) => v != null);
112	      const best = p50s.length ? Math.min(...p50s) : 0;
113	      for (const l of lanes) {
114	        l.els.big.textContent = l.lat ? fmtMs(l.lat.p50) : '–';
115	        l.els.unit.textContent = 'p50 · rolling 10s';
116	        l.els.side.textContent = l.lat ? `p95 ${fmtMs(l.lat.p95)}` : '–';
117	        // bar = relative speed: the fastest lane fills the track, a lane at
118	        // 2× its p50 reaches halfway. Lower latency literally looks faster.
119	        const p50 = l.lat && l.lat.p50 > 0 ? l.lat.p50 : 0;
120	        l.els.bar.style.width = `${Math.max(2, p50 > 0 ? (best / p50) * 100 : 2)}%`;
121	        l.els.crown.textContent = lanes.length > 1 && best > 0 && p50 === best ? '👑' : '';
122	      }
123	    } else { // reliability: ALL ops — for session, clones count alongside pushes
124	      const attempts = (l) => l.good + l.errs;
125	      const pcts = lanes.map((l) => (attempts(l) ? (l.good / attempts(l)) * 100 : null));
126	      const best = Math.max(...pcts.map((p) => (p == null ? -1 : p)));
127	      lanes.forEach((l, i) => {
128	        const pct = pcts[i];
129	        l.els.big.textContent = pct == null ? '–' : `${pct.toFixed(pct === 100 ? 0 : 1)}%`;
130	        l.els.unit.textContent = `of ${fmtInt(attempts(l))} attempts succeeded`;
131	        l.els.side.textContent = `${fmtInt(l.errs)} failures`;
132	        l.els.bar.style.width = `${Math.max(2, pct == null ? 2 : pct)}%`;
133	        l.els.crown.textContent = lanes.length > 1 && pct != null && pct === best ? '👑' : '';
134	      });
135	    }
136	  }
137	
138	  function tickClock() {
139	    if (state.done) return;
140	    if (!state.curLevel) { clock.textContent = '–:––'; return; }
141	    const l = state.curLevel;
142	    const { remain, warming } = levelCountdown(l);
143	    clock.textContent = `${Math.floor(remain / 60)}:${String(remain % 60).padStart(2, '0')}`;
144	    phase.textContent = warming ? 'warming up' : `c=${l.concurrency} · racing`;
145	  }
146	
147	  // The caption is built from the run's actual workload so it never overstates:
148	  // what the agents do, what the counters mean, and what's inside the numbers.
149	  function renderScience() {
150	    if (!state.hello) return;
151	    const w = state.hello.workload;
152	    const commit = `${w.files_min}–${w.files_max} files × ${fmtInt(w.file_size)} B`;
153	    const shape = {
154	      branch: `each commits ${commit} and force-pushes its own branch to one shared repo`,
155	      repo: `spread across multiple repos, each commits ${commit} and pushes its own branch`,
156	      clone: 'each shallow-clones the base branch, discards it, and repeats',
157	      session: `each shallow-clones, pushes ${w.session_commits} checkpoint commits (${commit}) to an ephemeral branch, abandons it, and repeats`,
158	    }[w.strategy] || '';
159	    const pack = w.strategy === 'clone' ? 'upload-pack' : 'packfile build + receive-pack';
160	    science.textContent =
161	      `What you're watching: ${state.hello.levels.join('/')} concurrent agents per forge — ${shape} — ` +
162	      `in a tight loop of real git over smart HTTP (${pack}). Identical workload on every lane, levels started simultaneously. ` +
163	      `Counters are successful ${opsNoun()}; rates are a 5 s rolling mean; latency is a rolling 10 s window percentile; ` +
164	      `reliability is successful ${w.strategy === 'session' ? 'operations (pushes and clones)' : opsNoun()} ÷ attempts ` +
165	      `(errors and CAS rejections count as failures)` +
166	      (w.warmup_sec > 0 ? `; the ${w.warmup_sec} s warm-up is excluded from final stats` : '') +
167	      `. The generator runs on this machine, so network round-trip to each forge is included in every number.`;
168	  }
169	
170	  function refinish() {
171	    finishBox.innerHTML = '';
172	    if (state.done) finish(state.done);
173	  }
174	
175	  function finish(ev) {
176	    clock.textContent = '0:00';
177	    phase.textContent = 'finished';
178	    // finalOf returns a target's result only when it's from the final level: a
179	    // target that died at a lower concurrency keeps that lower-level result in
180	    // state.finals, and comparing it against other targets' final-level numbers
181	    // would award an invalid winner.
182	    const finalOf = (r) => (r.final && r.final._level === state.finalLevel ? r.final : null);
183	    const rows = (state.hello ? state.hello.targets : [])
184	      .map((t) => ({ t, lane: state.lanes[t.id], final: state.finals[t.id] }))
185	      .filter((r) => r.lane);
186	    if (!rows.length || !rows.some((r) => r.lane.ok > 0)) return;
187	
188	    // Rank and phrase the verdict by the metric being watched. Final stats
189	    // come from the measured window (level_result), not the live counters.
190	    // An exact tie on the ranked value is reported as one — never a winner.
191	    let verdict = '';
192	    let tie = false;
193	    if (metric === 'latency') {
194	      // A target with no final-level result, no successes, or a non-positive
195	      // p50 (an all-failed level publishes p50_ms: 0) has no comparable latency;
196	      // rank it as Infinity so it sorts last and can never win.
197	      const latOf = (r) => { const f = finalOf(r); return f && f.ok > 0 && f.p50_ms > 0 ? f.p50_ms : Infinity; };
198	      rows.sort((a, b) => latOf(a) - latOf(b));
199	      const [win, next] = rows;
200	      if (latOf(win) === Infinity) {
201	        tie = true; // nobody has a comparable latency — suppress a lone winner
202	        verdict = ' — no comparable latency at the final level';
203	      } else {
204	        tie = next && latOf(next) === latOf(win);
205	        verdict = tie
206	          ? ` — ${fmtMs(finalOf(win).p50_ms)} median on both`
207	          : next && latOf(next) !== Infinity
208	            ? ` — ${(finalOf(next).p50_ms / finalOf(win).p50_ms).toFixed(1)}× lower median latency`
209	            : ' — only target with a comparable median latency';
210	      }
211	    } else if (metric === 'reliability') {
212	      const pct = (r) => (r.lane.good + r.lane.errs ? r.lane.good / (r.lane.good + r.lane.errs) : -1);
213	      rows.sort((a, b) => pct(b) - pct(a) || b.lane.good - a.lane.good);
214	      const [win, next] = rows;
215	      if (next) {
216	        tie = pct(win) === pct(next);
217	        verdict = tie
218	          ? ` — ${(pct(win) * 100).toFixed(1)}% success across the board`
219	          : ` — ${(pct(win) * 100).toFixed(1)}% vs ${(pct(next) * 100).toFixed(1)}% success`;
220	      }
221	    } else {
222	      rows.sort((a, b) => b.lane.ok - a.lane.ok);
223	      const [win, next] = rows;
224	      if (next && next.lane.ok > 0) {
225	        tie = win.lane.ok === next.lane.ok;
226	        verdict = tie
227	          ? ` — ${fmtInt(win.lane.ok)} ${opsNoun()} each`
228	          : ` — ${(win.lane.ok / next.lane.ok).toFixed(1)}× more ${opsNoun()}`;
229	      }
230	    }
231	    const win = rows[0];
232	
233	    finishBox.append(h('div', { class: 'race-podium card' },
234	      h('div', { class: 'race-winner' },
235	        tie
236	          ? ['🤝 dead heat', verdict]
237	          : ['🏆 ', h('b', { style: { color: targetColor(win.t.id) } }, win.t.name), ' wins', verdict]),
238	      h('table', { class: 'results' },
239	        h('thead', {}, h('tr', {}, h('th', {}, ''), h('th', {}, 'target'), h('th', {}, opsNoun()),
240	          h('th', {}, `${opsNoun()}/s`), h('th', {}, 'p50'), h('th', {}, 'p95'), h('th', {}, 'failures'))),
241	        h('tbody', {}, rows.map((r, i) => {
242	          const f = finalOf(r); // final-level result only; a stale earlier level shows '–'
243	          return h('tr', {},
244	            h('td', {}, tie && i < 2 ? '🥇' : ['🥇', '🥈', '🥉'][i] || ''),
245	            h('td', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(r.t.id), marginRight: '6px' } }), r.t.name),
246	            h('td', {}, fmtInt(r.lane.ok)),
247	            h('td', {}, f ? f.ops_per_sec.toFixed(1) : '–'),
248	            h('td', {}, f ? fmtMs(f.p50_ms) : '–'),
249	            h('td', {}, f ? fmtMs(f.p95_ms) : '–'),
250	            h('td', { class: r.lane.errs > 0 ? 'num-bad' : '' }, fmtInt(r.lane.errs)));
251	        })))));
252	    const saved = resultsSavedBanner(ev);
253	    if (saved) finishBox.append(saved);
254	  }
255	
256	  const handlers = {
257	    hello(ev) {
258	      state.hello = ev;
259	      state.isClone = ev.workload.strategy === 'clone';
260	      state.isSession = ev.workload.strategy === 'session';
261	      buildLanes(ev.targets);
262	      renderScience();
263	      badge.className = 'badge running';
264	      badge.textContent = 'running';
265	    },
266	    level_start(ev) { state.curLevel = ev; },
267	    bucket(ev) {
268	      if (!state.hello) return;
269	      // Normalize this bucket's counts to a per-second rate: the first
270	      // post-warmup bucket and the tail flush cover only a fraction of a second
271	      // (ev.dt_ms), so a raw count would over/understate the rolling rate.
272	      const dt = (ev.dt_ms || 1000) / 1000;
273	      for (const t of state.hello.targets) {
274	        const v = ev.targets[String(t.id)];
275	        const l = state.lanes[t.id];
276	        if (!v || !l) continue;
277	        const ok = state.isClone ? v.clone_ok || 0 : v.ok;
278	        let good = ok;
279	        let err = (state.isClone ? v.clone_err || 0 : v.err) + (v.cas || 0);
280	        if (state.isSession) {
281	          // Session agents clone AND push: both count toward reliability even
282	          // though throughput/latency lanes track the pushes.
283	          good += v.clone_ok || 0;
284	          err += v.clone_err || 0;
285	        }
286	        l.ok += ok;
287	        l.good += good;
288	        l.errs += err;
289	        if (dt > 0) {
290	          l.rates.push(ok / dt);
291	          if (l.rates.length > 5) l.rates.shift();
292	        }
293	        // Latency is the collector's rolling 10s-window percentile, reported
294	        // every bucket regardless of this second's completions. Track it whenever
295	        // the window has data (p95 > 0) and clear it to null when the window
296	        // empties, so a stalled target stops displaying — and winning with — a
297	        // stale latency.
298	        const lp = state.isClone
299	          ? { p50: v.clone_p50_ms, p95: v.clone_p95_ms }
300	          : { p50: v.p50_ms, p95: v.p95_ms };
301	        l.lat = lp.p95 > 0 ? lp : null;
302	        l.pop = l.pop || ok > 0;
303	      }
304	      // Coalesce DOM work: a finished-run replay delivers thousands of buckets
305	      // back-to-back, so lane updates (and the pop's forced reflow) run once
306	      // per animation frame, not once per bucket.
307	      if (!raf) {
308	        raf = requestAnimationFrame(() => {
309	          raf = 0;
310	          updateLanes();
311	          for (const l of Object.values(state.lanes)) {
312	            if (!l.pop) continue;
313	            l.pop = false;
314	            if (metric !== 'pushes') continue;
315	            l.els.big.classList.remove('pop');
316	            void l.els.big.offsetWidth; // restart the pop animation
317	            l.els.big.classList.add('pop');
318	          }
319	        });
320	      }
321	    },
322	    level_result(ev) {
323	      // Stamp each result with its level so the podium can tell a target's
324	      // final-level result from a stale earlier one it kept after dying.
325	      for (const [id, r] of Object.entries(ev.targets)) state.finals[id] = { ...r, _level: ev.level_index };
326	      state.finalLevel = Math.max(state.finalLevel, ev.level_index);
327	    },
328	    target_error(ev) {
329	      const t = state.hello?.targets.find((x) => x.id === ev.target);
330	      banners.append(h('div', { class: 'banner error' },
331	        `✖ ${t ? t.name : `target ${ev.target}`}: ${ev.message}${ev.fatal ? ' — out of the race' : ''}`));
332	      if (t && ev.fatal) state.lanes[t.id]?.lane.classList.add('dead');
333	    },
334	    run_done(ev) {
335	      state.done = ev;
336	      badge.className = `badge ${ev.state}`;
337	      badge.textContent = ev.state;
338	      refinish();
339	      if (es) { es.close(); es = null; }
340	    },
341	  };
342	
343	  es = openRunStream(runId, handlers);
344	  es.onerror = () => { if (!state.done) { badge.className = 'badge'; badge.textContent = 'reconnecting…'; } };
345	  ticker = setInterval(tickClock, 250);
346	
347	  return () => {
348	    if (es) es.close();
349	    clearInterval(ticker);
350	    if (raf) cancelAnimationFrame(raf);
351	  };
352	}
353

