133	// its own time.Now after being scheduled — which would skew the sample clock
134	// against the window/dt_ms timestamps. The close is a happens-before edge, so
135	// the write is visible to every Hold() that returns.
136	func (b *StartBarrier) Fire() {
137		b.firedAt = time.Now()
138		close(b.release)
139	}
140	
141	// FiredAt is the shared start instant, valid after Fire (for the coordinator) or
142	// after Hold returns (for a participant).
143	func (b *StartBarrier) FiredAt() time.Time { return b.firedAt }
144	
145	// RunLevel runs a single concurrency level: build c agents, wait at the
146	// barrier so all targets start together, run for warmup+duration, then fold
147	// the samples into one result. It blocks for the full level window (or until
148	// ctx is cancelled). barrier may be nil to run without synchronization.
149	func (r *Runner) RunLevel(ctx context.Context, c int, barrier *StartBarrier) (LevelResult, error) {
150		var clone *cloneConfig
151		var sess *sessionConfig
152		switch r.w.Strategy {
153		case "clone":
154			clone = &cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef}
155		case "session":
156			sess = &sessionConfig{
157				cloneConfig: cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef},
158				commits:     r.w.SessionCommits,
159			}
160		}
161		agents := make([]*agent, c)
162		for i := range c {
163			repoPath := r.target.Repos[0]
164			if r.w.Strategy == "repo" {
165				repoPath = r.target.Repos[i%len(r.target.Repos)]
166			}
167			node := r.ep.nodes[i%len(r.ep.nodes)]
168			ref := DestRef(r.w.BranchPrefix, r.w.RunID, c, i)
169			a, err := newAgent(i, repoPath, node, ref, r.ep.objFmt, &r.w.Commit, r.creds, r.httpc, clone, sess, r.sink)
170			if err != nil {
171				if barrier != nil {
172					barrier.Arrive() // don't leave the coordinator's Await hanging
173				}
174				return LevelResult{}, fmt.Errorf("new agent %d: %w", i, err)
175			}
176			agents[i] = a
177		}
178	
179		// Agents are built; wait for every target before starting the clock, so the
180		// measured window begins at the same instant on each and the comparison is
181		// fair regardless of per-target setup time.
182		if barrier != nil {
183			barrier.Arrive()
184			barrier.Hold()
185		}
186	
187		total := r.w.Warmup + r.w.Duration
188		// Origin the sample clock AND the context deadline on the same instant — the
189		// barrier's shared fire time when there is one. Using FiredAt for the offset
190		// origin but a scheduled-now timeout for the deadline let a target released
191		// late run a full `total` from its late start, recording samples past the
192		// shared window end that summarize then miscounts against the fixed duration.
193		// Deriving the deadline from FiredAt()+total stops every target together.
194		// Single-target CLI runs have no barrier and just start now.
195		start := time.Now()
196		if barrier != nil {
197			start = barrier.FiredAt()
198		}
199		lvlCtx, cancel := context.WithDeadline(ctx, start.Add(total))
200		defer cancel()
201		var wg sync.WaitGroup
202		for _, a := range agents {
203			wg.Add(1)
204			go func(a *agent) {
205				defer wg.Done()
206				a.run(lvlCtx, start)
207			}(a)
208		}
209		wg.Wait()
210	
211		var all []Sample
212		for _, a := range agents {
213			all = append(all, a.samples...)
214		}
215		reposUsed := 1
216		if r.w.Strategy == "repo" {
217			reposUsed = min(c, len(r.target.Repos))
218		}
219		return summarize(all, c, r.w.Strategy, reposUsed, len(r.ep.nodes), r.w.Warmup, r.w.Duration, r.w.CommitDesc()), nil
220	}
221	
222	func setupGeneric(t Target) (credentialProvider, *endpoint, error) {
223		if t.Remote == "" {
224			return nil, nil, errors.New("-remote required (e.g. https://gitlab.com); for entiredb also pass -token-url and -jurisdiction")
225		}
