227			return nil, nil, errors.New("github.com is sha1; drop -object-format sha256")
228		}
229		objFmt, err := parseObjectFormat(t.ObjectFmt)
230		if err != nil {
231			return nil, nil, err
232		}
233		user := t.User
234		if user == "" {
235			user = "x-access-token" // token forges ignore the username; the token is the password
236		}
237		return staticCreds{username: user, password: t.Secret}, newGenericEndpoint(t.Remote, objFmt), nil
238	}
239	
240	func setupEntiredb(ctx context.Context, t Target, httpc *http.Client) (credentialProvider, *endpoint, error) {
241		var missing []string
242		if t.Remote == "" {
243			missing = append(missing, "-remote (cluster base URL)")
244		}
245		if t.TokenURL == "" {
246			missing = append(missing, "-token-url")
247		}
248		if t.Jurisdiction == "" {
249			missing = append(missing, "-jurisdiction")
250		}
251		if len(missing) > 0 {
252			return nil, nil, fmt.Errorf("entire target (selected by -token-url/-jurisdiction) also needs: %s", strings.Join(missing, ", "))
253		}
254		clientID := t.ClientID
255		if clientID == "" {
256			clientID = "entire-cli"
257		}
258		creds := newJurisdictionCreds(httpc, t.TokenURL, t.Jurisdiction, clientID, t.Secret, "token")
259		ep, err := newEntireEndpoint(ctx, t.Remote, t.ObjectFmt, t.Repos[0], creds, httpc)
260		if err != nil {
261			return nil, nil, err
262		}
263		return creds, ep, nil
264	}
