1	package server
2	
3	import (
4		"testing"
5	
6		"github.com/entireio/forgemark/internal/bench"
7	)
8	
9	func TestNewDemoRunnerValidation(t *testing.T) {
10		w := bench.Workload{Strategy: "branch", Concurrency: []int{1}}
11		ok := func(remote string) {
