40	    h('div', { class: 'run-head' },
41	      h('h1', {}, `Run ${runId}`), badge, workloadNote, h('span', { class: 'spacer' }),
42	      h('a', { class: 'race-alt', href: `#race/${runId}` }, '⚡ race view'), cancelBtn),
43	    banners, levelsStrip, tiles, chartsBox, resultsBox);
44	
45	  const warned = sessionStorage.getItem(`fm-warn-${runId}`);
46	  if (warned) {
47	    for (const wtext of JSON.parse(warned)) banners.append(h('div', { class: 'banner warn' }, '⚠ ' + wtext));
48	  }
49	
50	  // --- charts are built once targets are known (hello) ---
51	  function buildCharts(targets) {
52	    const isClone = state.strategy === 'clone';
53	    const isSession = state.strategy === 'session';
54	    const bands = () => state.warmups;
55	
56	    const mk = (title, note, opts) => {
57	      const el = h('div');
58	      const head = h('div', { class: 'chart-head' }, h('h2', {}, title), note ? h('span', { class: 'u-note' }, note) : null);
59	      const card = h('div', { class: 'card chart-card' }, head, el);
60	      chartsBox.append(card);
61	      return { el, head, chart: timeChart(el, opts) };
62	    };
63	
64	    const tputSeries = targets.map((t) => ({ label: t.name, color: targetColor(t.id) }));
65	    if (isSession) {
66	      for (const t of targets) tputSeries.push({ label: `${t.name} clones`, color: targetColor(t.id), dash: [5, 5] });
67	    }
68	    charts.tput = mk(isClone ? 'Clone throughput' : 'Push throughput',
69	      isClone ? 'successful clones per second' : 'successful pushes per second' + (isSession ? ' · dashed = clones/s' : ''),
70	      { series: tputSeries, unit: fmtNum, bands }).chart;
71	
72	    const latHead = mk('Latency', `rolling 10s window · shaded = warm-up`, {
73	      series: targets.map((t) => ({ label: t.name, color: targetColor(t.id) })),
74	      unit: fmtMs, bands,
75	    });
76	    charts.lat = latHead.chart;
77	    const seg = h('div', { class: 'seg' }, ['p50', 'p95', 'p99'].map((p) =>
78	      h('button', { type: 'button', class: p === pct ? 'on' : '', onclick: (ev) => {
79	        pct = p;
80	        for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.textContent === p);
81	        refeedLatency();
82	      } }, p)));
83	    latHead.head.append(seg);
84	
85	    const errSeries = [];
86	    for (const t of targets) errSeries.push({ label: `${t.name} err`, color: targetColor(t.id) });
87	    for (const t of targets) errSeries.push({ label: `${t.name} cas`, color: targetColor(t.id), dash: [5, 5] });
88	    charts.err = mk('Errors & contention', 'failures/s (solid) and CAS rejections/s (dashed)',
89	      { series: errSeries, unit: fmtNum, bands }).chart;
90	  }
91	
92	  function refeedLatency() {
93	    if (!charts.lat) return;
94	    charts.lat.setAll(state.latRows.map((r) => [r.ts, ...r.vals.map((v) => (v ? v[pct] : null))]));
95	  }
96	
97	  function buildTiles(targets) {
98	    tiles.innerHTML = '';
99	    for (const t of targets) {
100	      state.totals[t.id] = { cas: 0, err: 0 };
101	      t._tile = {
102	        ops: h('b', {}, '–'), p95: h('b', {}, '–'), errs: h('b', {}, '0'),
103	        label: h('div', { class: 'tlabel' }, t.remote),
104	        err: h('div', { class: 'terr', style: { display: 'none' } }),
105	        root: null,
106	      };
107	      t._tile.root = h('div', { class: 'tile', style: { '--tcolor': targetColor(t.id) } },
108	        h('div', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id) } }), t.name),
109	        t._tile.label,
110	        h('div', { class: 'stats' },
111	          h('div', { class: 'stat' }, t._tile.ops, h('span', {}, 'ops/s')),
112	          h('div', { class: 'stat' }, t._tile.p95, h('span', {}, 'p95 (10s)')),
113	          h('div', { class: 'stat' }, t._tile.errs, h('span', {}, 'errors'))),
114	        t._tile.err);
115	      tiles.append(t._tile.root);
116	    }
117	  }
118	
119	  function renderLevels() {
120	    levelsStrip.innerHTML = '';
121	    const levels = state.hello ? state.hello.levels : [];
122	    const curIdx = state.curLevel ? state.curLevel.level_index : -1;
123	    levels.forEach((c, i) => {
124	      const cls = state.done || i < curIdx ? 'done' : i === curIdx ? 'current' : '';
125	      levelsStrip.append(h('span', { class: `level-chip ${cls}` }, `c=${c}`));
126	    });
127	    levelsStrip.append(progressBar, progressNote);
128	  }
129	  const progressBar = h('div', { class: 'progress' }, h('div', { style: { width: '0%' } }));
130	  const progressNote = h('span', { class: 'progress-note' });
131	
132	  function tickProgress() {
133	    if (!state.curLevel || state.done) { progressBar.firstChild.style.width = state.done ? '100%' : '0%'; return; }
134	    const l = state.curLevel;
135	    const { total, elapsed, remain, warming } = levelCountdown(l);
136	    progressBar.firstChild.style.width = `${(elapsed / total) * 100}%`;
137	    progressNote.textContent =
138	      `level ${l.level_index + 1}: ${warming ? 'warming up' : 'measuring'} · ${remain}s left`;
139	  }
140	
141	  // --- results table ---
142	  const resultCols = [
143	    ['c', (r) => r.concurrency], ['ok', (r) => r.ok], ['ops/s', (r) => r.ops_per_sec.toFixed(1)],
144	    ['p50', (r) => fmtMs(r.p50_ms)], ['p95', (r) => fmtMs(r.p95_ms)], ['p99', (r) => fmtMs(r.p99_ms)],
145	    ['p99.9', (r) => fmtMs(r.p999_ms)], ['max', (r) => fmtMs(r.max_ms)],
146	    ['cas', (r) => r.cas_failures], ['err', (r) => r.other_errors],
147	  ];
148	  let resultsTable = null;
149	  function appendLevelResult(ev) {
150	    if (!resultsTable) {
151	      resultsTable = h('table', { class: 'results' },
152	        h('thead', {}, h('tr', {}, h('th', {}, 'target'), resultCols.map(([name]) => h('th', {}, name)))),
153	        h('tbody'));
154	      resultsBox.append(h('div', { class: 'card' }, h('h2', {}, 'Level results'), resultsTable));
155	    }
156	    const tbody = resultsTable.querySelector('tbody');
157	    let first = true;
158	    for (const t of state.hello.targets) {
159	      const r = ev.targets[String(t.id)];
160	      if (!r) continue;
161	      tbody.append(h('tr', { class: first ? 'lvl-first' : '' },
162	        h('td', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id), marginRight: '6px' } }), t.name),
163	        resultCols.map(([, fn], ci) => h('td', { class: ci >= 8 && fn(r) > 0 ? 'num-bad' : '' }, String(fn(r))))));
164	      first = false;
165	    }
166	  }
167	
168	  // --- event handlers ---
169	  const handlers = {
170	    hello(ev) {
171	      state.hello = ev;
172	      state.strategy = ev.workload.strategy;
173	      workloadNote.textContent = `${ev.workload.strategy} · sweep ${ev.levels.join(', ')} · ${ev.workload.duration_sec}s/level`;
174	      buildTiles(ev.targets);
175	      buildCharts(ev.targets);
176	      renderLevels();
177	      cancelBtn.style.display = '';
178	      badge.className = 'badge running';
179	      badge.textContent = 'running';
180	    },
181	    target_ready(ev) {
182	      const t = state.hello?.targets.find((x) => x.id === ev.target);
183	      if (t && t._tile) t._tile.label.textContent = `${ev.label} · ${ev.object_format}${ev.nodes > 1 ? ` · ${ev.nodes} nodes` : ''}`;
184	    },
185	    level_start(ev) {
186	      state.curLevel = ev;
187	      const t0 = Date.parse(ev.at) / 1000;
188	      state.warmups.push({ from: t0, to: t0 + ev.warmup_sec });
189	      renderLevels();
190	    },
191	    bucket(ev) {
192	      if (!state.hello) return;
193	      const targets = state.hello.targets;
194	      const isClone = state.strategy === 'clone';
195	      const vals = targets.map((t) => ev.targets[String(t.id)] || null);
196	
197	      // A bucket's ok is a count over the bucket's measured duration, which is
198	      // ~1s for a steady tick but fractional for the first post-warm-up bucket
199	      // and the tail flush. Normalize count → ops/s by that duration so those
200	      // points aren't misleading; dt_ms absent (legacy series) falls back to 1s.
201	      const dt = (ev.dt_ms || 1000) / 1000;
202	      const rate = (n) => (dt > 0 ? n / dt : null);
203	
204	      // throughput (+ dashed clone series for session)
205	      const tputVals = vals.map((v) => (v ? rate(isClone ? v.clone_ok || 0 : v.ok) : null));
206	      if (state.strategy === 'session') tputVals.push(...vals.map((v) => (v ? rate(v.clone_ok || 0) : null)));
207	      charts.tput.push(ev.t, tputVals);
208	
209	      // latency rows retained for percentile switching. Gate on the rolling
210	      // window having data (p95 > 0), NOT this second's completion count: the
211	      // collector keeps a 10s window precisely so a quiet second doesn't blank
212	      // the line, and BucketStats.ok is only that one second's successes.
213	      const latVals = vals.map((v) => {
214	        if (!v) return null;
215	        const p = isClone
216	          ? { p50: v.clone_p50_ms, p95: v.clone_p95_ms, p99: v.clone_p99_ms }
217	          : { p50: v.p50_ms, p95: v.p95_ms, p99: v.p99_ms };
218	        return p.p95 > 0 ? p : null;
219	      });
220	      state.latRows.push({ ts: ev.t, vals: latVals });
221	      charts.lat.push(ev.t, latVals.map((v) => (v ? v[pct] : null)));
222	
223	      // Total failed operations = push errors + clone errors. Summing both is
224	      // correct for every strategy (the other is 0), and it's essential for
225	      // session, where a run whose clones all fail would otherwise show zero
226	      // errors and zero throughput.
227	      // Normalize by dt like throughput: this chart is failures/s, so the
228	      // fractional first/tail buckets must be divided by their duration too, or
229	      // the error and CAS rates read high/low at the window edges.
230	      charts.err.push(ev.t, [
231	        ...vals.map((v) => (v ? rate((v.err || 0) + (v.clone_err || 0)) : null)),
232	        ...vals.map((v) => (v ? rate(v.cas || 0) : null)),
233	      ]);
234	
235	      // tiles
236	      targets.forEach((t, i) => {
237	        const v = vals[i];
238	        if (!v || !t._tile) return;
239	        const tot = state.totals[t.id];
