91	func TestStartRunValidation(t *testing.T) {
92		_, ts, _ := newTestServer(t)
93	
94		post := func(body string) (int, string) {
95			res, err := http.Post(ts.URL+"/api/runs", "application/json", strings.NewReader(body))
96			if err != nil {
97				t.Fatal(err)
98			}
99			defer func() { _ = res.Body.Close() }()
100			var out map[string]any
101			_ = json.NewDecoder(res.Body).Decode(&out)
102			msg, _ := out["error"].(string)
103			return res.StatusCode, msg
104		}
105	
106		if code, msg := post(`{"targets":[{"remote":"demo://x"}]}`); code != http.StatusBadRequest || !strings.Contains(msg, "confirm_authorized") {
107			t.Fatalf("unconfirmed POST = %d %q, want 400 confirm_authorized", code, msg)
108		}
109		if code, msg := post(`{"confirm_authorized":true,"targets":[]}`); code != http.StatusBadRequest || !strings.Contains(msg, "target") {
110			t.Fatalf("no-targets POST = %d %q, want 400", code, msg)
111		}
112		if code, msg := post(`{"confirm_authorized":true,"workload":{"strategy":"bogus"},"targets":[{"remote":"demo://x"}]}`); code != http.StatusBadRequest || !strings.Contains(msg, "strategy") {
113			t.Fatalf("bad-strategy POST = %d %q, want 400", code, msg)
114		}
115		if code, msg := post(`{"confirm_authorized":true,"targets":[{"remote":"demo://x","secret":"tok","secret_source":"gh"}]}`); code != http.StatusBadRequest || !strings.Contains(msg, "not both") {
116			t.Fatalf("secret+source POST = %d %q, want 400 not-both", code, msg)
117		}
118		if code, msg := post(`{"confirm_authorized":true,"targets":[{"remote":"demo://x","secret_source":"bogus"}]}`); code != http.StatusBadRequest || !strings.Contains(msg, "secret_source") {
119			t.Fatalf("unknown-source POST = %d %q, want 400 secret_source", code, msg)
120		}
121		// Real (non-demo) targets are fast-failed at the request, not left to die
122		// mid-run inside NewRunner. demo:// targets skip these checks.
123		if code, msg := post(`{"confirm_authorized":true,"targets":[{"remote":"https://git.example","secret":"tok"}]}`); code != http.StatusBadRequest || !strings.Contains(msg, "no repos") {
